function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function quizGen(items, opts){
  opts=opts||{}; var seed=opts.seed!=null?opts.seed:1; var r=rngFactory(seed);
  var lines = (items && items.length!=null && typeof items!=='string') ? items.slice() : String(items||'').split(/\n/);
  var pairs=[];
  for(var i=0;i<lines.length;i++){
    var s=String(lines[i]).trim(); if(!s) continue;
    var p=s.split(/\s*[:：]\s*/);
    var q=(p[0]||'').trim(), a=p.slice(1).join(' ').trim();
    if(q && a) pairs.push({q:q, a:a});
  }
  if(!pairs.length) return {ok:false, reason:'未识别到「问题: 答案」格式的条目'};
  var out=[];
  var LETTERS=['A','B','C','D','E','F'];
  for(var j=0;j<pairs.length;j++){
    if(opts.mode==='choice'){
      var pool=[];
      for(var k=0;k<pairs.length;k++){ if(k!==j) pool.push(pairs[k].a); }
      var used={}; used[pairs[j].a]=1; var distract=[];
      var guard=0;
      while(distract.length<3 && pool.length && guard<200){
        guard++;
        var cand=pool[Math.floor(r()*pool.length)];
        if(!cand || used[cand]) continue;
        used[cand]=1; distract.push(cand);
      }
      var arr=distract.concat([pairs[j].a]);
      for(var s2=arr.length-1;s2>0;s2--){ var kk=Math.floor(r()*(s2+1)); var tt=arr[s2]; arr[s2]=arr[kk]; arr[kk]=tt; }
      var ls=['Q'+(j+1)+'. '+pairs[j].q];
      for(var m2=0;m2<arr.length;m2++) ls.push('   '+LETTERS[m2]+') '+arr[m2]);
      ls.push('   答案：'+LETTERS[arr.indexOf(pairs[j].a)]);
      out.push(ls.join('\n'));
    } else {
      out.push('Q'+(j+1)+'. '+pairs[j].q+'\n   答案：'+pairs[j].a);
    }
  }
  return {ok:true, text:out.join('\n\n'), count:pairs.length};
}

var EXPORTS={quizGen:quizGen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.QuizGenForgePure = EXPORTS; }
